11 hints.ai_socktype = SOCK_STREAM;
12
13 rv = getaddrinfo("www.example.com", "http", &hints, &servinfo);
14 if (rv != 0) {
15 fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(rv));
