17 }
18
19 // loop through all the results and connect to the first we can
20 for(p = servinfo; p != NULL; p = p->ai_next) {
21 if ((sockfd = socket(p->ai_family, p->ai_socktype,
22 p->ai_protocol)) == -1) {
23 perror("socket");
24 continue;
